define(["core/ajax"],function(Ajax){"use strict";const allowed=new Set(["activity.getContext","course.getActivities","course.getNavigation","completion.get","completion.complete","progress.load","progress.save","progress.getStatus","progress.saveStatus","tracking.record","tracking.summary","attempt.get","attempt.start","attempt.finish","questions.get","questions.submit"]);const init=config=>{const frame=document.querySelector('.mod-mcp-document[data-cmid="'+String(config.cmid)+'"]');if(!frame){return}console.log("[mod_mcp/bridge] Inicializando para cmid:",config.cmid);const sendTheme=()=>{if(!frame.isConnected||!frame.contentWindow||typeof window.getComputedStyle!=="function"){return}const computed=window.getComputedStyle(frame);if(!computed){return}const variables={};let count=0;let total=0;for(let i=0;i<computed.length&&count<256;i++){const name=computed.item(i);if(typeof name!=="string"||!/^--[a-zA-Z][a-zA-Z0-9_-]{0,127}$/.test(name)){continue}const value=computed.getPropertyValue(name).trim();if(!value||value.length>4096||total+name.length+value.length>65536){continue}variables[name]=value;total+=name.length+value.length;count++}let mode=null;let ancestor=frame;while(ancestor){if(typeof ancestor.getAttribute==="function"){const attribute=ancestor.getAttribute("data-bs-theme");if(attribute==="light"||attribute==="dark"){mode=attribute;break}}ancestor=ancestor.parentElement}frame.contentWindow.postMessage({channel:"mod_mcp",type:"theme",variables:variables,mode:mode},"*")};if(typeof window.MutationObserver==="function"){const observer=new window.MutationObserver(sendTheme);let ancestor=frame;while(ancestor){observer.observe(ancestor,{attributes:true,attributeFilter:["class","style","data-bs-theme","data-theme"]});ancestor=ancestor.parentElement}}if(typeof window.matchMedia==="function"){const preference=window.matchMedia("(prefers-color-scheme: dark)");if(typeof preference.addEventListener==="function"){preference.addEventListener("change",sendTheme)}else if(typeof preference.addListener==="function"){preference.addListener(sendTheme)}}window.addEventListener("load",sendTheme);const requestMeasurement=()=>{if(frame.isConnected&&frame.contentWindow){console.log("[mod_mcp/bridge] Solicitando medição de altura ao iframe.");frame.contentWindow.postMessage({channel:"mod_mcp",type:"measure"},"*")}};window.addEventListener("message",event=>{if(event.source!==frame.contentWindow){return}const msg=event.data;if(!msg||msg.channel!=="mod_mcp"){return}if(msg.type==="ready"){console.log("[mod_mcp/bridge] SDK sinalizou ready; solicitando altura.");requestMeasurement();sendTheme();return}if(msg.type==="resize"){if(typeof msg.height!=="number"||!Number.isFinite(msg.height)||msg.height<=0||msg.height>1e5){return}const height=Math.ceil(msg.height)+"px";console.log("[mod_mcp/bridge] Altura recebida do iframe:",height);if(frame.style.height!==height){frame.style.height=height;console.log("[mod_mcp/bridge] Altura aplicada ao iframe:",height)}return}if(msg.type!=="request"||typeof msg.id!=="string"||!/^mcp-[a-zA-Z0-9-]{1,48}$/.test(msg.id)||!allowed.has(msg.action)||!msg.payload||typeof msg.payload!=="object"||Array.isArray(msg.payload)){return}let payload;try{payload=JSON.stringify(msg.payload);if(payload.length>262144){return}}catch(e){return}const send=message=>{if(frame.isConnected&&event.source===frame.contentWindow){frame.contentWindow.postMessage(Object.assign({channel:"mod_mcp",type:"response",id:msg.id},message),"*")}};Ajax.call([{methodname:"mod_mcp_dispatch",args:{cmid:Number(config.cmid),action:msg.action,payload:payload,preview:Boolean(config.preview)}}])[0].then(result=>{send({ok:true,result:JSON.parse(result.json)});return result}).catch(error=>{send({ok:false,error:error.errorcode||"requestfailed"})})});frame.addEventListener("load",()=>{console.log("[mod_mcp/bridge] Evento iframe.load; solicitando altura.");requestMeasurement();sendTheme()});if(frame.dataset&&frame.dataset.src){frame.src=frame.dataset.src;delete frame.dataset.src}requestMeasurement();sendTheme()};return{init:init}});